static int uacce_put_queue(struct uacce_queue *q)
{
    struct uacce_device *uacce = q->uacce;
    if ((q->state == UACCE_Q_STARTED) && uacce->ops->stop_queue)
        uacce->ops->stop_queue(q);
    if ((q->state == UACCE_Q_INIT || q->state == UACCE_Q_STARTED) && uacce->ops->put_queue)
        uacce->ops->put_queue(q);
    q->state = UACCE_Q_ZOMBIE;
    return 0;
}
<text>
case UACCE_CMD_PUT_Q:
    ret = uacce_put_queue(q);
    break;
<text>
Reason:
The original uacce_put_queue does not check the state of the queue or the validity of the uacce->ops pointer before calling ops->stop_queue and ops->put_queue. During a race condition between uacce_fops_release and uacce_remove, the ops pointer may become NULL or point to freed memory, causing a null pointer dereference or use-after-free. Additionally, calling uacce_put_queue directly from the ioctl may release resources before they are actually finished, since the queue might still be in STARTED state.

The code statements that fix the bug are:
<text>
static int uacce_stop_queue(struct uacce_queue *q)
{
    struct uacce_device *uacce = q->uacce;
    if (q->state != UACCE_Q_STARTED)
        return 0;
    if (uacce->ops->stop_queue)
        uacce->ops->stop_queue(q);
    q->state = UACCE_Q_INIT;
    return 0;
}

static void uacce_put_queue(struct uacce_queue *q)
{
    struct uacce_device *uacce = q->uacce;
    uacce_stop_queue(q);
    if (q->state != UACCE_Q_INIT)
        return;
    if (uacce->ops->put_queue)
        uacce->ops->put_queue(q);
    q->state = UACCE_Q_ZOMBIE;
}
<text>
case UACCE_CMD_PUT_Q:
    ret = uacce_stop_queue(q);
    break;
<text>
Reason:
The fix introduces uacce_stop_queue as a separate function that only stops the queue if it is in the UACCE_Q_STARTED state, then transitions it to UACCE_Q_INIT. The UACCE_CMD_PUT_Q ioctl now only stops the queue without calling put_queue, deferring actual resource release to the final cleanup (uacce_put_queue) which is called only when the file descriptor is closed or device is removed. The new uacce_put_queue first calls uacce_stop_queue, then checks if the queue is in UACCE_Q_INIT state before calling ops->put_queue. This ensures ops is only accessed when the queue is in a valid state and after proper synchronization, preventing access to freed or NULL pointers during the race condition.

